<script lang="ts">
	// @ts-nocheck
	import data from '$data'
	import { navigate } from '../lib/navigation'
	import { smart_api } from '../lib/smart-api'
	import TaskStatusBadge from '../components/TaskStatusBadge.svelte'
	let tasks = $state([]), input_fields = $state([]), output_fields = $state([]), query = $state(''), status = $state('all'), filters = $state({}), refresh_seconds = $state(0), refreshing = $state(false), refresh_error = $state(''), refresh_initialized = false, sort_key = $state('started'), sort_direction = $state('desc'), page = $state(1), per_page = $state(10)
	data.smart_workflow_tasks.subscribe((items) => tasks = [...items].sort((a, b) => new Date(b.created || b.started_at || 0).getTime() - new Date(a.created || a.started_at || 0).getTime()))
	data.smart_workflow_input_fields.subscribe((items) => input_fields = [...items].sort((a,b) => (a.order || 0) - (b.order || 0)))
	data.smart_workflow_output_fields.subscribe((items) => output_fields = [...items].sort((a,b) => (a.order || 0) - (b.order || 0)))
	data.smart_workflow_runner_config.subscribe((items) => { if (!refresh_initialized && items[0]) { refresh_seconds = Number(items[0].default_refresh_seconds || 0); refresh_initialized = true } })
	const visible_columns = () => [...input_fields.map(field => ({...field, source:'input'})), ...output_fields.map(field => ({...field, source:'output'}))].filter(field => field.show_in_list)
	const dedicated_filters = () => input_fields.filter(field => field.searchable)
	const date = (value) => value ? new Date(value).toLocaleString() : '—'
	const active = () => tasks.filter((task) => !['success', 'failed', 'interrupted'].includes(String(task.status || '').toLowerCase()))
	function value(task, field) { return (field.source === 'output' ? task.output : (task.input_summary || task.input_variables))?.[field.name] }
	function text_value(value) { return value === undefined || value === null || value === '' ? '—' : typeof value === 'object' ? JSON.stringify(value) : String(value) }
	function hover_value(value) { const text = text_value(value); return text.length > 1000 ? `${text.slice(0, 1000)}…` : text }
	const visible = $derived(tasks.filter((task) => {
		const haystack = `${task.title || ''} ${task.submitted_by || ''} ${JSON.stringify(task.input_summary || task.input_variables || {})}`.toLowerCase()
		if ((status !== 'all' && task.status !== status) || (query.trim() && !haystack.includes(query.trim().toLowerCase()))) return false
		return dedicated_filters().every((field) => !String(filters[field.name] || '').trim() || text_value(value(task, {...field, source:'input'})).toLowerCase().includes(String(filters[field.name]).trim().toLowerCase()))
	}).sort((left, right) => {
		const sortable = (task) => sort_key.startsWith('field:') ? text_value(value(task, visible_columns().find(field => `field:${field.source}:${field.name}` === sort_key))) : sort_key === 'task' ? String(task.title || task.smart_thread_id || '') : sort_key === 'status' ? String(task.status || '') : sort_key === 'progress' ? Number(task.progress_percent || 0) : sort_key === 'duration' ? Number(task.duration_ms || 0) : sort_key === 'cost' ? Number(task.provider_cost || 0) : new Date(task.started_at || task.created || 0).getTime()
		const compare = sortable(left) > sortable(right) ? 1 : sortable(left) < sortable(right) ? -1 : 0; return sort_direction === 'asc' ? compare : -compare
	}))
	const total_pages = $derived(Math.max(1, Math.ceil(visible.length / Number(per_page))))
	const paged = $derived(visible.slice((page - 1) * Number(per_page), page * Number(per_page)))
	function sort_by(key) { if (sort_key === key) sort_direction = sort_direction === 'asc' ? 'desc' : 'asc'; else { sort_key = key; sort_direction = key === 'task' || key === 'status' ? 'asc' : 'desc' }; page = 1 }
	function sort_label(key) { return sort_key === key ? (sort_direction === 'asc' ? '↑' : '↓') : '↕' }
	function cost(task) { return task.provider_cost == null ? '—' : String(task.provider_cost) }
	$effect(() => { query; status; filters; per_page; page = Math.min(page, total_pages) })
	async function refresh_active() { if (refreshing || !active().length) return; refreshing = true; refresh_error = ''; try { await Promise.all(active().map((task) => smart_api.refresh_task(task.id))) } catch (err) { refresh_error = err instanceof Error ? err.message : String(err) } finally { refreshing = false } }
	$effect(() => { if (!refresh_seconds) return; const timer = window.setInterval(() => void refresh_active(), refresh_seconds * 1000); return () => window.clearInterval(timer) })
</script>
<section class="page"><div class="page-head"><div><h2>Workflow tasks</h2><p>Every SMART run is saved here with its thread, inputs, progress, assets, and result.</p></div><div class="head-actions"><button class="secondary" onclick={() => refresh_active()} disabled={refreshing || !active().length}>{refreshing ? 'Refreshing…' : `Refresh ${active().length || ''}`}</button><button onclick={() => navigate('/?view=new')}>Create task</button></div></div>
	<section class="toolbar card"><input bind:value={query} placeholder="Search title, creator, or submitted input…" aria-label="Search tasks" /><select bind:value={status} aria-label="Filter tasks by status"><option value="all">All statuses</option><option value="queued">Queued</option><option value="idle">Idle</option><option value="running">Running</option><option value="interrupted">Needs input</option><option value="success">Success</option><option value="failed">Failed</option></select><label><span>Auto refresh</span><select bind:value={refresh_seconds}><option value={0}>Off</option><option value={5}>Every 5 sec</option><option value={10}>Every 10 sec</option><option value={30}>Every 30 sec</option><option value={60}>Every minute</option></select></label>{#each dedicated_filters() as field (field.id)}<label>{field.label || field.name}<input value={filters[field.name] || ''} placeholder={`Filter ${field.label || field.name}`} oninput={(event) => filters = {...filters, [field.name]: event.currentTarget.value}} /></label>{/each}</section>
	{#if refresh_error}<p class="error">{refresh_error}</p>{/if}
	<section class="card table-wrap">{#if visible.length}<table><thead><tr><th><button class="sort" onclick={() => sort_by('task')}>Task {sort_label('task')}</button></th><th><button class="sort" onclick={() => sort_by('status')}>Status {sort_label('status')}</button></th>{#each visible_columns() as field (field.source + field.id)}<th><button class="sort" onclick={() => sort_by(`field:${field.source}:${field.name}`)}>{field.label || field.name} {sort_label(`field:${field.source}:${field.name}`)}</button></th>{/each}<th><button class="sort" onclick={() => sort_by('progress')}>Progress {sort_label('progress')}</button></th><th><button class="sort" onclick={() => sort_by('cost')}>Cost {sort_label('cost')}</button></th><th><button class="sort" onclick={() => sort_by('started')}>Started {sort_label('started')}</button></th><th><button class="sort" onclick={() => sort_by('duration')}>Duration {sort_label('duration')}</button></th><th></th></tr></thead><tbody>{#each paged as task (task.id)}<tr><td><strong title={hover_value(task.title || task.smart_thread_id || 'Untitled task')}>{task.title || task.smart_thread_id || 'Untitled task'}</strong><small>{task.submitted_by || 'Hangar user'}</small></td><td><TaskStatusBadge status={task.status} /></td>{#each visible_columns() as field (field.source + field.id)}<td class="field-cell" title={hover_value(value(task, field))}>{text_value(value(task, field))}</td>{/each}<td><div class="progress"><i style={`width:${task.progress_percent || (task.status === 'success' ? 100 : 0)}%`}></i></div><small>{task.progress_percent || (task.status === 'success' ? 100 : 0)}%</small></td><td><strong>{cost(task)}</strong></td><td>{date(task.started_at || task.created)}</td><td>{task.duration_ms ? `${Math.round(task.duration_ms / 1000)}s` : '—'}</td><td><button class="link" onclick={() => navigate(`/?task=${encodeURIComponent(task.id)}`)}>View</button></td></tr>{/each}</tbody></table><footer class="pagination"><span>{visible.length} task{visible.length === 1 ? '' : 's'} · Page {page} of {total_pages}</span><label>Rows <select bind:value={per_page}><option value={10}>10</option><option value={25}>25</option><option value={50}>50</option></select></label><button class="secondary" onclick={() => page -= 1} disabled={page <= 1}>Previous</button><button class="secondary" onclick={() => page += 1} disabled={page >= total_pages}>Next</button></footer>{:else}<div class="empty"><strong>{tasks.length ? 'No tasks match this filter.' : 'No workflow tasks yet.'}</strong><span>{tasks.length ? 'Change the search or filters.' : 'Create the first task to run this SMART workflow.'}</span>{#if !tasks.length}<button onclick={() => navigate('/?view=new')}>Create task</button>{/if}</div>{/if}</section>
</section>
<style>.page{width:min(1180px,100%);margin:0 auto;display:grid;gap:1rem}.page-head,.head-actions{display:flex;justify-content:space-between;gap:.6rem;align-items:center}h2,p{margin:0}h2{font-size:1.2rem;font-weight:600}p,small{color:var(--muted-ink-color,#637083)}button{border:0;border-radius:7px;padding:.62rem .8rem;color:white;background:var(--accent-color,#3159db);font:inherit;font-weight:600;cursor:pointer}button:disabled{opacity:.65;cursor:default}.secondary{color:var(--ink-color,#172033);background:#eaf0f8}.card{border:1px solid var(--border-color,#dbe2ec);border-radius:var(--panel-radius,10px);background:var(--panel-background,#fff);overflow:hidden}.toolbar{padding:.75rem;display:grid;grid-template-columns:minmax(220px,1fr) 150px 170px;gap:.65rem;align-items:end}.toolbar label,.filters label{display:grid;gap:.3rem;color:var(--muted-ink-color,#637083);font-size:.75rem;font-weight:650;text-transform:uppercase}.filters{display:flex;flex-wrap:wrap;gap:.7rem;padding:.7rem;align-items:end}.filters>span{width:100%;color:#66748a;font-size:.72rem;font-weight:650;text-transform:uppercase}.filters label{min-width:180px}.filters label{font-size:.68rem}input,select{box-sizing:border-box;width:100%;min-height:38px;border:1px solid var(--border-color,#dbe2ec);border-radius:6px;padding:0 .65rem;color:var(--ink-color,#172033);background:white;font:inherit}table{width:100%;border-collapse:collapse}th,td{padding:.85rem 1rem;border-bottom:1px solid var(--border-color,#dbe2ec);text-align:left}th{color:var(--muted-ink-color,#637083);font-size:.73rem;text-transform:uppercase}.sort{padding:0;color:inherit;background:transparent;font-size:inherit;font-weight:650;text-transform:inherit}td small{display:block;margin-top:.2rem}.field-cell{max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:.78rem ui-monospace,SFMono-Regular,monospace}.progress{width:100px;height:7px;overflow:hidden;border-radius:999px;background:#e8edf4}.progress i{display:block;height:100%;border-radius:inherit;background:var(--accent-color,#3159db)}.link{color:var(--accent-color,#3159db);background:transparent}.pagination{display:flex;align-items:center;justify-content:flex-end;gap:.5rem;padding:.7rem .85rem;color:var(--muted-ink-color,#637083);font-size:.8rem}.pagination span{margin-right:auto}.pagination label{display:flex;align-items:center;gap:.35rem}.pagination select{width:auto;min-height:30px;padding:0 .35rem}.empty{min-height:240px;display:grid;place-items:center;align-content:center;gap:.65rem;text-align:center}.empty span{color:var(--muted-ink-color,#637083)}.error{margin:0;color:var(--danger-color,#cc3b45)}@media(max-width:760px){.page-head{align-items:start;flex-direction:column}.toolbar{grid-template-columns:1fr}.table-wrap{overflow:auto}table{min-width:900px}.pagination{min-width:900px}}</style>
